-- Migration 005 — Blog post generation tracking
--
-- Goal: track which blog posts were generated by the daily cron job
-- so the admin panel can distinguish AI-generated drafts from manually
-- created ones, and surface them with a "Generated" badge for review.
--
-- Run:
--   npx wrangler d1 execute herlonmoura_crm --remote --file=wrangler/d1/migrations/005_blog_generated.sql

ALTER TABLE blog_posts ADD COLUMN generated BOOLEAN DEFAULT 0;

CREATE INDEX IF NOT EXISTS idx_blog_generated ON blog_posts(generated) WHERE generated = 1;

-- Mark existing posts with author 'AI' as generated (they came from the same source)
UPDATE blog_posts SET generated = 1 WHERE author = 'AI' AND generated = 0;
